#include "muse_hint_ui.h"
#include "muse_dialog.h"
static void draw(lv_event_t *e){lv_event_stop_processing(e);lv_obj_t *o=lv_event_get_target_obj(e);lv_area_t at;lv_obj_get_coords(o,&at);muse_dialog_rect_t rects[MUSE_DIALOG_RECT_COUNT];int n=muse_dialog_rects(lv_obj_get_width(o),lv_obj_get_height(o),rects,MUSE_DIALOG_RECT_COUNT);for(int i=0;i<n;i++){lv_draw_rect_dsc_t d;lv_draw_rect_dsc_init(&d);d.bg_color=lv_color_hex(rects[i].rgb);d.bg_opa=255;lv_area_t a={at.x1+rects[i].x,at.y1+rects[i].y,at.x1+rects[i].x+rects[i].w-1,at.y1+rects[i].y+rects[i].h-1};lv_draw_rect(lv_event_get_layer(e),&d,&a);}}
void muse_hint_panel_create(muse_hint_panel_t *p,lv_obj_t *parent,const lv_font_t *font){p->frame=lv_obj_create(parent);lv_obj_remove_style_all(p->frame);lv_obj_remove_flag(p->frame,LV_OBJ_FLAG_CLICKABLE|LV_OBJ_FLAG_SCROLLABLE);lv_obj_add_flag(p->frame,LV_OBJ_FLAG_HIDDEN);lv_obj_set_size(p->frame,224,60);lv_obj_set_pos(p->frame,137,318);lv_obj_add_event_cb(p->frame,draw,LV_EVENT_DRAW_MAIN|LV_EVENT_PREPROCESS,NULL);p->label=lv_label_create(p->frame);lv_obj_set_style_text_font(p->label,font,0);lv_obj_set_style_text_color(p->label,lv_color_hex(0xF5EDF9),0);lv_obj_set_style_text_align(p->label,LV_TEXT_ALIGN_CENTER,0);lv_obj_set_style_text_line_space(p->label,2,0);lv_obj_set_width(p->label,200);lv_label_set_long_mode(p->label,LV_LABEL_LONG_MODE_WRAP);lv_obj_remove_flag(p->label,LV_OBJ_FLAG_CLICKABLE);lv_label_set_text(p->label,"");}
void muse_hint_panel_sync(muse_hint_panel_t *p,bool visible){if(!p->frame)return;const char *text=lv_label_get_text(p->label);visible=visible&&text[0]&&!lv_obj_has_flag(p->label,LV_OBJ_FLAG_HIDDEN);lv_obj_set_flag(p->frame,LV_OBJ_FLAG_HIDDEN,!visible);if(!visible)return;lv_point_t size;lv_text_get_size(&size,text,lv_obj_get_style_text_font(p->label,0),0,2,200,LV_TEXT_FLAG_NONE);int h=size.y;if(h<16)h=16;if(h>40)h=40;if(p->height!=h){p->height=h;lv_obj_set_height(p->frame,h+20);lv_obj_set_y(p->frame,378-h-20);lv_obj_set_height(p->label,h);lv_obj_center(p->label);}}
